#!/usr/bin/env bash
# run_job2.sh -- drive the whole DSP48E2 attribute sweep (job 2).
#
# Usage (on the cluster, from the job directory):
#   ./run_job2.sh [PART] [OUT_ROOT]
#
# Defaults: PART=xcvu3p-ffvc1517-2-e, OUT_ROOT=./out
# Prerequisites: vivado on PATH, variants/ generated by
#   python3 gen_dsp_variants.py dsp_variant_table.tsv variants
#   (or pass VARIANTS_DIR to override the variants location).
#
# Steps:
#   1. Resolve one fixed DSP site with pick_dsp_site.tcl (once).
#   2. Run v000 (baseline) then v001..v055 in manifest order, one
#      Vivado batch run per variant, via run_dsp_variant.tcl.
#   3. After each run, check dsp.bit/.rbt/.ll exist; append one line
#      per run to runs.txt (id, attribute, variant, part, site,
#      Vivado version, status). On any failure: record FAIL with the
#      Vivado log tail, and STOP. A failed run is never silently
#      skipped, and later runs never proceed past it, because a gap
#      in the sweep would corrupt the diff analysis.
#
# Vivado runs are sequential, never parallel: each run is a full
# synthesis/place/route, and parallel runs on a shared cluster node
# would fight for memory and make failures uninterpretable.
#
# No em dashes anywhere.
set -u

PART="${1:-xcvu3p-ffvc1517-2-e}"
OUT_ROOT="${2:-./out}"
VARIANTS_DIR="${VARIANTS_DIR:-./variants}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if ! command -v vivado >/dev/null 2>&1; then
  echo "ERROR: vivado not on PATH" >&2
  exit 1
fi
if [ ! -f "$VARIANTS_DIR/manifest.tsv" ]; then
  echo "ERROR: $VARIANTS_DIR/manifest.tsv not found; run gen_dsp_variants.py first" >&2
  exit 1
fi

mkdir -p "$OUT_ROOT"
RUNS_TXT="$OUT_ROOT/runs.txt"
{
  echo "job: 2 (DSP48E2 attribute sweep)"
  echo "part: $PART"
  echo "started: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo "variants: $VARIANTS_DIR"
} > "$RUNS_TXT"

echo "resolving fixed DSP site on $PART ..."
vivado -mode batch -source "$SCRIPT_DIR/pick_dsp_site.tcl" \
  -tclargs "$PART" "$OUT_ROOT/site.txt" > "$OUT_ROOT/pick_site.log" 2>&1
if [ ! -s "$OUT_ROOT/site.txt" ]; then
  echo "ERROR: site resolution failed; see $OUT_ROOT/pick_site.log" >&2
  echo "site resolution: FAIL (see pick_site.log)" >> "$RUNS_TXT"
  exit 1
fi
SITE="$(cat "$OUT_ROOT/site.txt")"
echo "site: $SITE" >> "$RUNS_TXT"
echo "fixed DSP site: $SITE"

# Manifest order is v000, v001, ...; skip the header line.
tail -n +2 "$VARIANTS_DIR/manifest.tsv" | while IFS="$(printf '\t')" read -r run_id attribute default variant verilog; do
  echo "=== $run_id ($attribute = $variant, default $default) ==="
  run_out="$OUT_ROOT/$run_id"
  mkdir -p "$run_out"
  if ! vivado -mode batch -source "$SCRIPT_DIR/run_dsp_variant.tcl" \
      -tclargs "$PART" "$VARIANTS_DIR/$verilog" "$SITE" "$run_out" \
      > "$run_out/vivado.log" 2>&1; then
    echo "FAIL $run_id: vivado exited nonzero; see $run_out/vivado.log" >&2
    echo "$run_id	$attribute	$variant	$PART	$SITE	FAIL vivado-nonzero" >> "$RUNS_TXT"
    exit 1
  fi
  missing=""
  for suffix in bit rbt ll; do
    if [ ! -f "$run_out/dsp.$suffix" ]; then
      missing="$missing dsp.$suffix"
    fi
  done
  # JOB2.md requires post_route.dcp and run_info.txt per run as well:
  # the checkpoint is the re-analysis input, and run_info.txt carries
  # the Vivado version the runs.txt line records. The .tcl script
  # writes both before its own output check, so a missing one here
  # means the run did not complete normally.
  for extra in post_route.dcp run_info.txt; do
    if [ ! -f "$run_out/$extra" ]; then
      missing="$missing $extra"
    fi
  done
  if [ -n "$missing" ]; then
    echo "FAIL $run_id: missing outputs:$missing" >&2
    echo "$run_id	$attribute	$variant	$PART	$SITE	FAIL missing:$missing" >> "$RUNS_TXT"
    exit 1
  fi
  vivado_version="$(grep '^vivado_version:' "$run_out/run_info.txt" | sed 's/^vivado_version: //')"
  echo "$run_id	$attribute	$variant	$PART	$SITE	OK $vivado_version" >> "$RUNS_TXT"
  echo "OK $run_id"
done
status=$?
if [ "$status" -ne 0 ]; then
  echo "job 2 STOPPED at a failed run; see $RUNS_TXT" >&2
  exit 1
fi
echo "finished: $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$RUNS_TXT"
echo "job 2 complete: $(grep -c $'\tOK ' "$RUNS_TXT") runs OK; see $RUNS_TXT"
